class Solution:
    def occurrencesOfElement(self, nums: list[int], queries: list[int], x: int) -> list[int]:
        indices = [i for i, val in enumerate(nums) if val == x]
        m = len(indices)
        return [indices[q - 1] if q <= m else -1 for q in queries]

class Solution {
public:
    vector<int> occurrencesOfElement(vector<int>& nums, vector<int>& queries, int x) {
        vector<int> indices;
        for (int i = 0; i < (int)nums.size(); ++i) {
            if (nums[i] == x) indices.push_back(i);
        }
        vector<int> ans;
        ans.reserve(queries.size());
        int m = indices.size();
        for (int q : queries) {
            if (q <= m) ans.push_back(indices[q - 1]);
            else ans.push_back(-1);
        }
        return ans;
    }
};

class Solution {
    public int[] occurrencesOfElement(int[] nums, int[] queries, int x) {
        List<Integer> indices = new ArrayList<>();
        for (int i = 0; i < nums.length; ++i) {
            if (nums[i] == x) indices.add(i);
        }
        int[] ans = new int[queries.length];
        int m = indices.size();
        for (int i = 0; i < queries.length; ++i) {
            int q = queries[i];
            ans[i] = q <= m ? indices.get(q - 1) : -1;
        }
        return ans;
    }
}

var occurrencesOfElement = function(nums, queries, x) {
    const indices = [];
    for (let i = 0; i < nums.length; ++i) {
        if (nums[i] === x) indices.push(i);
    }
    const m = indices.length;
    return queries.map(q => q <= m ? indices[q - 1] : -1);
};
